process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
const TOK=process.env.GH_TOKEN||''; const REPO=process.env.GH_REPO||'raimis079-creator/petshop-bridge';
const WP='https://dev.avesa.lt';
const AUTH='Basic '+Buffer.from(process.env.WP_USER+':'+process.env.WP_APP_PASS).toString('base64');
const B64='';
const KAND=JSON.parse(Buffer.from('','base64').toString('utf8'));
const out={versija:'H041'};
async function put(path,buf,msg){
  let sha=null;
  try{const g=await fetch(`https://api.github.com/repos/${REPO}/contents/${path}`,{headers:{'Authorization':'Bearer '+TOK,'User-Agent':'b'}});if(g.status===200)sha=(await g.json()).sha;}catch(e){}
  const b={message:msg,content:buf.toString('base64')}; if(sha) b.sha=sha;
  return (await fetch(`https://api.github.com/repos/${REPO}/contents/${path}`,{method:'PUT',headers:{'Authorization':'Bearer '+TOK,'Content-Type':'application/json','User-Agent':'b'},body:JSON.stringify(b)})).status;
}
async function api(p,o={}){ const r=await fetch(WP+p,{...o,headers:{Authorization:AUTH,'Content-Type':'application/json',...(o.headers||{})}}); return {s:r.status,t:await r.text()}; }
async function seka(u,max=5){
  const k=[]; let cur=u;
  for(let i=0;i<max;i++){
    let r; try{ r=await fetch(cur,{redirect:'manual'}); }catch(e){ k.push({st:-1}); break; }
    const loc=r.headers.get('location');
    k.push({u:cur.replace('https://dev.avesa.lt',''),st:r.status,xrb:r.headers.get('x-redirect-by')||''});
    if(r.status>=300&&r.status<400&&loc){ cur=loc.startsWith('http')?loc:'https://dev.avesa.lt'+loc; continue; }
    break;
  }
  return k;
}
let snipId=null;
try{
  const ls=await api('/wp-json/code-snippets/v1/snippets');
  let sar=[]; try{sar=JSON.parse(ls.t);}catch(e){}
  for(const s of (Array.isArray(sar)?sar:[])){
    if(String(s.name||'').startsWith('TEMP') && s.active){
      await api('/wp-json/code-snippets/v1/snippets/'+s.id,{method:'POST',body:JSON.stringify({id:s.id,active:false})});
    }
  }
  const cr=await api('/wp-json/code-snippets/v1/snippets',{method:'POST',body:JSON.stringify({name:'TEMP H041 404 kandidatai',code:Buffer.from(B64,'base64').toString('utf8'),scope:'global',active:true,priority:5})});
  let j=null; try{j=JSON.parse(cr.t);}catch(e){}
  snipId=j?j.id:null; out.snip=snipId||'KLAIDA';
  await new Promise(r=>setTimeout(r,9000));

  const k404=[]; const veikia=[]; let klaidos=0;
  for(const x of KAND){
    const k=await seka('https://dev.avesa.lt'+x.p);
    const p=k[0], g=k[k.length-1];
    if(p.st===-1){ klaidos++; continue; }
    if(p.st===404 || g.st===404) k404.push(x);
    else veikia.push({p:x.p,c:x.c,st:p.st,gal:g.st});
    await new Promise(s=>setTimeout(s,55));
  }
  out.suvestine={viso:KAND.length, veikia:veikia.length, k404:k404.length, klaidos,
    veikia_clicks:veikia.reduce((a,b)=>a+b.c,0), k404_clicks:k404.reduce((a,b)=>a+b.c,0)};

  /* kandidatai per WP */
  const rk=await fetch(WP+'/?ps_h041=KAND',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(k404)});
  const tk=await rk.text();
  try{ out.kandidatai=JSON.parse(tk); }catch(e){ out.kand_zalias=tk.slice(0,400); out.k404_be_kand=k404; }
}catch(e){ out.klaida=String(e).slice(0,400); }
try{ if(snipId) await api('/wp-json/code-snippets/v1/snippets/'+snipId,{method:'POST',body:JSON.stringify({id:snipId,active:false})}); }catch(e){}
const zlib=await import('zlib');
await put('screenshots/h041.json.gz', zlib.gzipSync(Buffer.from(JSON.stringify(out))), 'h041 404 kandidatai');
